import { deepStrictEqual, throws } from 'node:assert/strict';
import { purchase, transfer } from './wallet';

for (const operation of ['purchase', 'transfer']) {
  for (const cents of [40, 100, 101]) {
    const from = { balance: 100 };
    const to = { balance: 20 };
    const run = () => operation === 'transfer'
      ? transfer(from, to, cents)
      : purchase(from, cents);

    if (cents > 100) {
      throws(run, /Insufficient funds/);
      deepStrictEqual([from.balance, to.balance], [100, 20]);
    } else {
      run();
      deepStrictEqual(
        [from.balance, to.balance],
        [100 - cents, operation === 'transfer' ? 20 + cents : 20],
      );
    }
  }
}
